const SB_URL='https://kekmppsuiiokdckdeolv.supabase.co';
const SB_KEY='process.env.SUPABASE_SERVICE_ROLE_KEY||''';
const input=$input.first().json;
const token=(input.token||'').replace(/^sk-/,'');
function authError(code,msg){return[{json:{_auth_error:true,error_code:code,message:msg}}]};
if(!token)return authError('AUTH_INVALID','Missing token');
try{
const tResp=await this.helpers.httpRequest({method:'GET',url:SB_URL+'/rest/v1/tokens?select=id,status,remain_quota,unlimited_quota&key=eq.'+encodeURIComponent(token)+'&limit=1',headers:{apikey:SB_KEY,Authorization:'Bearer '+SB_KEY},json:true,timeout:5000});
if(!tResp.length||tResp[0].status!==1)return authError('AUTH_INVALID','Invalid token');
const r=tResp[0];
return $input.all().map(function(item){var j=item.json;j._sb_key=SB_KEY;j._sb_url=SB_URL;j.token=input.token;return{json:j}});
}catch(e){return authError('AUTH_ERROR',String(e.message||e).slice(0,100))}

// Build 10 slot prompts for mxou image generation
const input = $input.first().json;
const draft = input.draft || input;
const title = draft.title || '未命名商品';
const sourceImages = draft.source_images || input.image_urls || [];
const mxouToken = input.mxou_token || '';
const mxouBase = input.mxou_base_url || 'https://api.mxou.cn';
const aspectRatio = input.image_aspect || '1080x1440';

// Phase 1: 白底图 (slot 0+1) — use original source images as reference
const phase1 = [
  {slot:'white_background_reference', order:0, prompt:'根据参考图生成白底参考图。严格保持参考图中的同一商品身份一致。纯白背景，只保留单个商品主体。真实摄影质感，光线均匀，边缘清晰。无人物，无动物，无额外道具，无文字，无场景。'},
  {slot:'multi_angle_white_background_image', order:1, prompt:'根据参考图做一个俄罗斯电商多角度产品白底图，要符合俄罗斯人民审美，突出商品多个角度与结构细节，让产品点击率更高。纯白背景，不得出现人物和动物。严格保持参考图中的同一商品身份一致。'},
];

// Phase 2: 8张图 (slot 2-9) — use multi_angle_white as cleaner reference
const phase2 = [
  {slot:'main_image', order:2, prompt:'根据参考图做一个俄罗斯电商主图，要符合俄罗斯人民审美，让产品点击率更高。严格保持参考图中的同一商品身份一致。画面以产品为主。'},
  {slot:'product_multi_info_image', order:3, prompt:'根据参考图做一个俄罗斯电商产品多维信息图，用信息图方式展示产品容量、尺寸、结构、材质等关键信息。要符合俄罗斯人民审美。画面以产品为主。'},
  {slot:'detail_image', order:4, prompt:'根据参考图做一个俄罗斯电商细节展示图，要符合俄罗斯人民审美。画面以产品为主。严格保持参考图中的同一商品身份一致。'},
  {slot:'social_proof_image', order:5, prompt:'根据参考图做一个俄罗斯电商好评如潮图，要符合俄罗斯人民审美，让整体画面更有故事感，让产品点击率更高。严格保持参考图中的同一商品身份一致。'},
  {slot:'usage_scene_image', order:6, prompt:'根据参考图做一个俄罗斯电商使用场景图(旅行场景)，要符合俄罗斯人民审美，让产品点击率更高。严格保持参考图中的同一商品身份一致。画面以产品为主。'},
  {slot:'usage_scene_image_2', order:7, prompt:'根据参考图做一个俄罗斯电商使用场景图(家庭场景)，要符合俄罗斯人民审美。严格保持参考图中的同一商品身份一致。'},
  {slot:'usage_scene_image_3', order:8, prompt:'根据参考图做一个俄罗斯电商使用场景图(商务出差场景)，要符合俄罗斯人民审美。严格保持参考图中的同一商品身份一致。'},
  {slot:'comparison_image', order:9, prompt:'根据参考图做一个俄罗斯电商多维对比图，要符合俄罗斯人民审美。对比表达必须中性、克制、真实。严格保持参考图中的同一商品身份一致。'},
];

const refs = sourceImages.filter(u => u && typeof u === 'string').slice(0, 4);

return [{json: {
  phase1, phase2, reference_urls: refs, mxou_token: mxouToken,
  mxou_base: mxouBase, aspect_ratio: aspectRatio, title, draft
}}];

// Collect phase 1 results: white_bg + multi_angle_white
const allInputs = $input.all();

function extractUrls(r) {
  let urls = [];
  if (r.data && Array.isArray(r.data)) urls = r.data.filter(d => d.url).map(d => d.url);
  if (urls.length === 0 && r.results && Array.isArray(r.results)) urls = r.results.filter(d => d.url).map(d => d.url);
  if (urls.length === 0) {
    const walk = (obj) => {
      if (!obj || typeof obj !== 'object') return;
      if (typeof obj === 'string' && (obj.startsWith('http://') || obj.startsWith('https://'))) { urls.push(obj); return; }
      if (Array.isArray(obj)) { obj.forEach(walk); return; }
      Object.values(obj).forEach(walk);
    };
    walk(r);
  }
  return [...new Set(urls)];
}

let whiteBgUrl = null;
let multiViewUrl = null;

for (const inp of allInputs) {
  const urls = extractUrls(inp.json);
  if (!whiteBgUrl && urls.length > 0) whiteBgUrl = urls[0];
  else if (whiteBgUrl && !multiViewUrl && urls.length > 0) multiViewUrl = urls[0];
}

// Use multi_angle_white as cleaner reference for phase 2
const cleanRef = multiViewUrl || whiteBgUrl;

return [{json: {
  white_bg_url: whiteBgUrl,
  multi_view_url: multiViewUrl,
  clean_reference: cleanRef,
}}];

const phase1Result = $input.first().json;
const cfg = $('① 构建Prompt').first().json;
const cleanRef = phase1Result.clean_reference;

if (!cleanRef) {
  // Fallback: use original refs
  return cfg.phase2.map(s => ({json: {...s, reference_urls: cfg.reference_urls, mxou_token: cfg.mxou_token, mxou_base: cfg.mxou_base, aspect_ratio: cfg.aspect_ratio}}));
}

// Use multi_angle_white as clean reference for all 8 followup images
const followupRefs = [cleanRef].concat(cfg.reference_urls).slice(0, 4);

return cfg.phase2.map(s => ({
  json: {...s, reference_urls: followupRefs, mxou_token: cfg.mxou_token, mxou_base: cfg.mxou_base, aspect_ratio: cfg.aspect_ratio}
}));

const r = $input.first().json;
let urls = [];
if (r.results && Array.isArray(r.results)) { urls = r.results.filter(d => d.url).map(d => d.url); }
else if (r.data && Array.isArray(r.data)) { urls = r.data.filter(d => d.url).map(d => d.url); }
if (urls.length === 0) {
  const walk = (obj) => {
    if (!obj || typeof obj !== 'object') return;
    if (typeof obj === 'string' && (obj.startsWith('http://') || obj.startsWith('https://'))) { urls.push(obj); return; }
    if (Array.isArray(obj)) { obj.forEach(walk); return; }
    Object.values(obj).forEach(walk);
  };
  walk(r);
}
urls = [...new Set(urls)];
return [{json: {slot: r.slot || $json.slot, urls, raw: r}}];

const all = $input.all();
const phase1 = $('③ 收集白底图').first().json;

const OZON_ORDER = [
  'main_image', 'usage_scene_image', 'usage_scene_image_2', 'usage_scene_image_3',
  'comparison_image', 'social_proof_image', 'product_multi_info_image',
  'detail_image', 'multi_angle_white_background_image', 'white_background_reference'
];

// Collect results
const results = {};
results['white_background_reference'] = {urls: phase1.white_bg_url ? [phase1.white_bg_url] : []};
results['multi_angle_white_background_image'] = {urls: phase1.multi_view_url ? [phase1.multi_view_url] : []};

for (const inp of all) {
  const j = inp.json;
  if (j.slot) results[j.slot] = {urls: j.urls || []};
}

// Build ordered generated images
const generated = [];
for (const slot of OZON_ORDER) {
  const r = results[slot];
  if (r && r.urls.length > 0) generated.push(...r.urls);
}

const total = generated.length;
const primaryImg = generated[0] || phase1.multi_view_url || phase1.white_bg_url || '';
const whiteBgImg = phase1.white_bg_url || '';

return [{json: {
  asset_manifest: {
    total_assets: total,
    primary_image: primaryImg,
    white_background_image: whiteBgImg,
    generated_images: generated,
    moderation_flags: [],
    retry_count: 0,
  },
  completed_slots: Object.values(results).filter(r => r.urls.length > 0).length,
  pending_slots: 10 - Object.values(results).filter(r => r.urls.length > 0).length,
  slot_results: results,
}}];
